css:
.label-container {
    width: 55mm;
    height: 25mm;
    padding: 0px;
    box-sizing: border-box;
    font-family: Arial, sans-serif;
    border: 0px solid #ddd;
    display: inline-block;
}

.itemcode-label {
    font-size: 18pt;
    font-weight: 700;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-bottom: 3px;
}

.itemname-label {
    font-size: 8pt;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-bottom: 3px;
}

html:
{% for item in doc.items %}
    {% set labels_to_print = item.custom_label_qty if item.custom_label_qty > 0 else 0 %}
    {% if labels_to_print > 0 %}
        {% for i in range(labels_to_print) %}
            <div class="label-container">
                <p class="itemcode-label">{{ item.item_code }}</p>
                <p class="itemname-label">{{ item.item_name }}</p>
                <p class="supplier-part-no">{{ item.supplier_part_no }}</p>
                <p class="docname-label">{{ doc.name }}</p>
            </div>
        {% endfor %}
    {% endif %}
{% endfor %}
